def chain_follows_chain(chain):
    chain_dict = {}
    for a, b in chain:
        chain_dict[a] = b

    stack = [chain[0]]
    result = []
    while stack:
        current = stack.pop()
        if current not in chain_dict:
            return None
        result.append(current)
        stack.append(chain_dict[current])

    return result

